import covers from "./covers.json";

/**
 * srcset for a project cover: the 780px WebP sibling (generated by
 * `npm run covers`, see scripts/covers.mjs) plus the original. Returns
 * undefined for images without a sibling (e.g. the 620px hero portrait), so
 * the <img> falls back to plain src.
 */
export function coverSrcSet(src) {
  if (!src) return undefined;
  const name = src.split("/").pop();
  const width = covers[name];
  if (!width) return undefined;
  const base = src.replace(/.(webp|jpe?g|png)$/i, "");
  return `${base}-780.webp 780w, ${src} ${width}w`;
}
